import { Task, TaskStatus } from '../../domain/entities/Task';
import { TaskRepository } from '../../domain/repositories/TaskRepository';

export class InMemoryTaskRepository implements TaskRepository {
  private tasks: Map<string, Task> = new Map();

  findById(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  findByProjectId(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId,
    );
  }

  findByProjectIdAndStatus(projectId: string, status: TaskStatus): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId && task.status === status,
    );
  }

  findByProjectIdAndAssignee(projectId: string, assigneeId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId && task.assigneeId === assigneeId,
    );
  }

  save(task: Task): void {
    this.tasks.set(task.id, task);
  }
}

=====SOURCE-END=====

